// MARK: Background (lib.rs)

/// Background of a slide, layout or master.
public indirect enum Background: Sendable, Equatable {
    case fill(fill: Fill)
    /// Theme background style reference (1001–1003) with a colour.
    case ref(idx: UInt32, color: ColorRef)
}

extension Background: JSONCodable {
    private static let variantNames = ["fill", "ref"]

    public func toJSON() -> JSON {
        switch self {
        case .fill(let fill):
            var o = JSONObject(["kind": .string("fill")])
            o.put("fill", fill)
            return .object(o)
        case .ref(let idx, let color):
            var o = JSONObject(["kind": .string("ref")])
            o.put("idx", idx)
            o.put("color", color)
            return .object(o)
        }
    }

    public init(fromJSON json: JSON) throws(JSONDecodeError) {
        let f = try JSONFields(json, "Background")
        let name = try f.tag("kind")
        let payload: JSON? = json
        switch name {
        case "fill":
            guard let payload else { throw JSONDecodeError("missing content for variant `fill`") }
            let vf = try JSONFields(payload, "Background::Fill")
            self = .fill(fill: try vf.required("fill"))
        case "ref":
            guard let payload else { throw JSONDecodeError("missing content for variant `ref`") }
            let vf = try JSONFields(payload, "Background::Ref")
            self = .ref(idx: try vf.required("idx"), color: try vf.required("color"))
        default:
            throw .unknownVariant(name, expected: Self.variantNames)
        }
    }
}

